func (l *Log) uploadBatch(writeRequests []*dynamodb.WriteRequest) error {
	for {
		c := &dynamodb.BatchWriteItemInput{
			RequestItems: map[string][]*dynamodb.WriteRequest{l.Tablename: writeRequests},
